// Só texto, curto. Nada de chamada à toa: vazio ou grande demais volta com aviso.
// modo "nota" (26/11/2026): devolve o serviço aprimorado + os valores lidos do rascunho (JSON validado depois).
const b = $('Recebe pedido do app').first().json.body || {};
const texto = String(b.texto ?? '').replace(/[\u0000-\u001f\u007f]/g, ' ').replace(/\s+/g, ' ').trim();
const modo = b.modo === 'nota' ? 'nota' : '';
let erro = '';
if (texto.length < 3) erro = 'Escreva a descrição primeiro.';
else if (texto.length > 800) erro = 'Texto grande demais para aprimorar de uma vez (máximo 800 letras).';
const corpo = modo === 'nota'
  ? { model: 'claude-haiku-5-5', max_tokens: 600, thinking: { type: 'disabled' }, system: "Você prepara a descrição de NFS-e de uma empresa de manutenção predial a partir de um rascunho do dono.\nservico: o serviço feito, corrigido (ortografia, acentos, concordância) e reescrito em linguagem técnica, formal e enxuta: frases curtas terminadas em ponto, palavras curtas, abreviações desfeitas, termos do ofício (substituição, instalação, reparo, vazamento). Não invente nem tire informação (quantidades, locais, peças, medidas). Acordo Ortográfico vigente (boia, ideia). Não escreva no servico valor total, valor de material, mão de obra nem \"material incluso\". Exceção: vários serviços, cada um com seu próprio valor: termine a frase de cada serviço com \" - R$ 1.250,00.\" (o valor dele).\ntipo: \"separado\" se o rascunho dá o valor do material junto com a mão de obra ou com o total; \"incluso\" se diz que o material está incluso/incluído; senão \"total\". Serralheria conta como material: valor de serralheria vai em material (e o rascunho passa a ser \"separado\" se também tiver mão de obra ou total).\ntotal, material, maoDeObra: valores em reais escritos no rascunho, como número (ex.: 1250.5); 0 se não escrito. Só copie números que são dinheiro (nunca quantidades). Não some nem calcule.",
      output_config: { effort: 'low', format: { type: 'json_schema', schema: {"type":"object","additionalProperties":false,"required":["servico","tipo","total","material","maoDeObra"],"properties":{"servico":{"type":"string"},"tipo":{"type":"string","enum":["total","incluso","separado"]},"total":{"type":"number"},"material":{"type":"number"},"maoDeObra":{"type":"number"}}} } },
      messages: [{ role: 'user', content: texto }] }
  : { model: 'claude-haiku-5-5', max_tokens: 500, thinking: { type: 'disabled' }, output_config: { effort: 'low' },
      system: "Você revisa textos curtos de documentos de uma empresa de manutenção predial (recibos, notas, orçamentos). Corrija ortografia, acentuação, concordância e pontuação e deixe o texto técnico, formal e enxuto, com os termos certos do ofício. Não invente nada e não tire informação: mantenha quantidades, locais, materiais, medidas e valores. Siga o Acordo Ortográfico vigente (boia, ideia, para, sem acento). Prefira termos técnicos (substituição, instalação, reparo, vazamento) e expanda abreviações óbvias. Responda só com o texto final, numa linha, sem aspas, título ou comentário.", messages: [{ role: 'user', content: texto }] };
return [{ json: { ok: !erro, erro, texto, modo, corpo } }];

// Resposta do Claude. Recusa, erro ou chave faltando viram um aviso simples (nada muda no campo).
const r = $json || {};
const e = $('Le entrada').first().json;
if (r.error || r.type === 'error') {
  const msg = JSON.stringify(r.error || r).toLowerCase();
  const semChave = /authentication|api[_ -]?key|401|credential/.test(msg);
  return [{ json: { ok: false, mensagem: semChave ? 'Falta a chave da Anthropic no n8n (credencial "Anthropic").' : 'O aprimorador não respondeu agora. Tente de novo em instantes.', detalhe: String((r.error && (r.error.type || r.error.message)) || r.message || '').slice(0, 120) } }];
}
if (r.stop_reason === 'refusal') return [{ json: { ok: false, mensagem: 'O aprimorador não quis mexer neste texto. Ajuste à mão.' } }];
if (r.stop_reason === 'max_tokens') return [{ json: { ok: false, mensagem: 'Texto longo demais para aprimorar: encurte e tente de novo.' } }];
const bruto = (Array.isArray(r.content) ? r.content : []).filter((c) => c.type === 'text').map((c) => c.text).join(' ').trim();
// Grafias antigas que às vezes escapam (Acordo Ortográfico): corrigidas aqui, sem gastar outra chamada.
const ACORDO = [[/b[óo]ia/g, 'boia'], [/B[óo]ia/g, 'Boia'], [/id[ée]ia/g, 'ideia'], [/Id[ée]ia/g, 'Ideia'], [/vôo/g, 'voo'], [/assembl[ée]ia/g, 'assembleia'], [/Assembl[ée]ia/g, 'Assembleia']];
const acordo = (t) => ACORDO.reduce((s, [de, para]) => s.replace(de, para), t);
const custo = { entrada: (r.usage || {}).input_tokens || 0, saida: (r.usage || {}).output_tokens || 0 };
// Validação da resposta da IA no modo "nota" (26/11/2026). Usada no nó "Monta resposta" do n8n e no teste local.
// A IA só copia; quem confere e soma é este código (valor que não está no rascunho é recusado).
function montaNota(rascunho, saida) {
  const num = (s) => {
    s = String(s);
    if (s.includes(',')) return Number(s.replace(/\./g, '').replace(',', '.'));
    const p = s.split('.');
    if (p.length > 1 && p.slice(1).every((x) => x.length === 3)) return Number(p.join(''));
    return Number(s);
  };
  const c = (v) => Math.round(Number(v || 0) * 100);
  const reais = (v) => 'R$ ' + (v / 100).toLocaleString('pt-BR', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const doTexto = new Set();
  for (const m of rascunho.matchAll(/\d+(?:[.,]\d+)*/g)) doTexto.add(c(num(m[0])));
  for (const m of rascunho.matchAll(/(\d+(?:[.,]\d+)?)\s*mil\b/gi)) doTexto.add(c(num(m[1]) * 1000));
  let o;
  try { o = typeof saida === 'string' ? JSON.parse(saida) : saida; } catch (e) { o = null; }
  if (!o || typeof o.servico !== 'string') return { ok: false, mensagem: 'O aprimorador voltou num formato estranho. Tente de novo.' };
  const tipo = ['total', 'incluso', 'separado'].includes(o.tipo) ? o.tipo : 'total';
  // Frases de valor ficam fora do texto do serviço: quem escreve é o sistema, sempre igual à regra.
  let servico = o.servico.replace(/\s*Valor (?:total|(?:do )?material|(?:da )?m[ãa]o de obra)\s*[=:]?\s*R\$\s*[\d.]+(?:,\d{2})?\.?/gi, '')
    .replace(/\s*Materia(?:l|is) inclu[íi]dos?(?: no valor)?\.?/gi, '').replace(/\.\s*[-–:]\s*R\$/g, ' - R$').replace(/\s+/g, ' ').trim();
  if (servico && !/[.!?]$/.test(servico)) servico += '.';
  if (servico.length < 3) return { ok: false, mensagem: 'Faltou o serviço no texto.' };
  let T = c(o.total), M = c(o.material), O = c(o.maoDeObra);
  const itens = [...servico.matchAll(/R\$\s*([\d.]+(?:,\d{1,2})?)/g)].map((m) => c(num(m[1])));
  // O total pode vir somado (soma dos serviços ou material + mão de obra): vale se a soma fecha com valores do texto.
  const somaItens = itens.length >= 2 ? itens.reduce((x, y) => x + y, 0) : -1;
  const fora = [T, M, O, ...itens].find((v) => v > 0 && !doTexto.has(v) && !(v === T && (T === somaItens || T === M + O)));
  if (fora) return { ok: false, mensagem: `Li ${reais(fora)}, mas esse valor não está no seu texto. Confira e aprimore de novo.` };
  if (tipo === 'separado') {
    if (!M) return { ok: false, mensagem: 'Para separar o material, escreva o valor do material no texto.' };
    if (T && O && M + O !== T) return { ok: false, mensagem: `Material (${reais(M)}) + mão de obra (${reais(O)}) não fecha com o total (${reais(T)}).` };
    if (!T) T = M + O;
    if (!(M > 0 && M < T)) return { ok: false, mensagem: 'Escreva o valor da mão de obra ou o total, além do material.' };
  } else if (itens.length >= 2) {
    const soma = itens.reduce((a, b) => a + b, 0);
    if (!T) T = soma;
    else if (T !== soma) return { ok: false, mensagem: `A soma dos serviços (${reais(soma)}) não bate com o total (${reais(T)}).` };
  }
  if (!(T > 0)) return { ok: false, mensagem: 'Não achei o valor no texto. Escreva o valor (ex.: "150") e aprimore de novo.' };
  return { ok: true, texto: servico, valores: { tipo, total: T / 100, material: tipo === 'separado' ? M / 100 : 0 } };
}

if (e.modo === 'nota') {
  const n = montaNota(e.texto, bruto);
  if (n.ok) n.texto = acordo(n.texto).slice(0, 1000);
  return [{ json: { ...n, original: e.texto, custo } }];
}
const texto = bruto.replace(/\s+/g, ' ').replace(/^["'“”]+|["'“”]+$/g, '');
if (!texto) return [{ json: { ok: false, mensagem: 'O aprimorador voltou vazio. Tente de novo.' } }];
return [{ json: { ok: true, texto: acordo(texto).slice(0, 1200), original: e.texto, custo } }];
